def cutOperatorNorm (T : LOne 𝕜 μ →L[𝕜] LOne 𝕜 ν) (A : Set Y) : ℝ :=
  sSup {r : ℝ | ∃ f : LOne 𝕜 μ, ‖f‖ ≤ 1 ∧
    r = (eLpNorm (A.indicator (T f)) 1 ν).toReal}

