def smallSetSup (T : LOne 𝕜 μ →L[𝕜] LOne 𝕜 ν) (Θ : Set Y) (δ : ℝ) : ℝ :=
  sSup {q : ℝ | ∃ B : Set Y, MeasurableSet B ∧ B ⊆ Θ ∧
    ν B < ENNReal.ofReal δ ∧ q = cutOperatorNorm T (Θᶜ ∪ B)}

